#!/usr/bin/env python3
import os
import re
import sys

# The root directory of the CuteApp project
PROJECT_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
GUI_DIR = os.path.join(PROJECT_ROOT, 'gui')

# Regex to detect `#include` of physics or compute/solvers headers, robust to whitespace
VIOLATION_REGEX = re.compile(
    r'^\s*#\s*include\s*[<"]\s*(physics/|compute/solvers/)',
    re.IGNORECASE
)

# Explicitly ignore autogenerated or third-party directories that might end up in gui/ 
IGNORE_DIRS = {
    'build', 
    'build-wasm',
    'third_party',
    '.git',
    '__pycache__'
}

def check_layering():
    print("--- Running Architecture Layering Checks ---")
    violations_found = False
    
    for root, dirs, files in os.walk(GUI_DIR):
        # Mutating dirs in-place to skip ignored directories
        dirs[:] = [d for d in dirs if d not in IGNORE_DIRS]
        
        for file in files:
            if not (file.endswith('.h') or file.endswith('.cpp') or file.endswith('.hpp') or file.endswith('.cc')):
                continue
                
            file_path = os.path.join(root, file)
            rel_path = os.path.relpath(file_path, PROJECT_ROOT)
            
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    for line_num, line in enumerate(f, 1):
                        sys.stdout.write(f"\rScanning {rel_path}...")
                        sys.stdout.flush()
                        if VIOLATION_REGEX.search(line):
                            violations_found = True
                            print(f"\n[ERROR] Layering violation detected:")
                            print(f"GUI layer must not directly include physics or solver headers.")
                            print(f"File: {rel_path}:{line_num}")
                            print(f"    {line.strip()}")
                            print(f"Action: Use ISimulationDriver and DTO interfaces instead.")
            except Exception as e:
                print(f"Warning: Could not read file {rel_path}: {e}")

    if violations_found:
        print("\nERROR: Architecture check failed. Build aborted.")
        sys.exit(1)
    else:
        print("\nOK: Architecture check passed. No layering violations found in GUI.")
        sys.exit(0)

if __name__ == "__main__":
    check_layering()
